'use strict';
/* ===== Utilidades ===== */
const $=(s,e=document)=>e.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=n=>String(n).padStart(2,'0');
const ymd=(d=new Date())=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const D=s=>new Date(s+'T12:00');
const addDays=(s,n)=>{const d=D(s);d.setDate(d.getDate()+n);return ymd(d)};
const diffDays=(a,b)=>Math.round((D(b)-D(a))/864e5);
const fmtD=s=>D(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','');
const fmtL=s=>D(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});
const num=v=>{const n=parseFloat(String(v).replace(',','.'));return isFinite(n)?n:null};
const r0=n=>Math.round(n),r1=n=>Math.round(n*10)/10;
const sum=(a,f=x=>x)=>a.reduce((s,x)=>s+(f(x)||0),0);
const days=n=>Array.from({length:n},(_,i)=>addDays(ymd(),-(n-1-i)));
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
const WD=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'],WDs=WD.map(x=>x.slice(0,3));
const SLOTS=[['cafe','Café da manhã'],['almoco','Almoço'],['lanche','Lanche'],['jantar','Jantar'],['extra','Refeição extra']];
const ACT={sedentario:['Sedentário (pouco ou nenhum exercício)',1.2],leve:['Leve (1–3 dias/semana)',1.375],moderado:['Moderado (3–5 dias/semana)',1.55],intenso:['Intenso (6–7 dias/semana)',1.725]};
const IC={home:'M3 11l9-8 9 8v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',dumb:'M6 6v12M18 6v12M3 9v6M21 9v6M6 12h12',food:'M7 3v8a2 2 0 0 0 2 2v8M11 3v8M7 7h4M17 3c-2 2-3 5-3 8h3v10',drop:'M12 3s6 6.5 6 11a6 6 0 0 1-12 0c0-4.5 6-11 6-11z',chart:'M4 20V4M4 20h16M8 16l4-5 3 3 5-7',more:'M5 12h.01M12 12h.01M19 12h.01',run:'M14 4.5a1.6 1.6 0 1 0 .01 0M9 21l2.5-5.5L9 13l2-5 4 2.5 3 .5M11.5 15.5L15 18v3M9 9l-3.5 1.5',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21a8 8 0 0 1 16 0',scale:'M5 4h14l2 16H3zM9 10a3 3 0 0 1 6 0',plus:'M12 5v14M5 12h14',check:'M5 12l5 5 9-10',trash:'M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13',edit:'M4 20h4L19 9l-4-4L4 16zM14 6l4 4',flag:'M5 21V4M5 4h12l-2 4 2 4H5',copy:'M9 9h11v11H9zM5 15V4h11',swap:'M7 4L3 8l4 4M3 8h14M17 20l4-4-4-4M21 16H7',down:'M12 4v12M6 12l6 6 6-6M5 21h14',bolt:'M13 2L4 14h7l-1 8 9-12h-7z'};
const ico=n=>`<svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="${IC[n]||''}"/></svg>`;
const bar=(p,c='')=>`<div class="bar ${c} ${p>100?'over':''}" role="progressbar" aria-valuenow="${r0(p)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${clamp(p)}%"></i></div>`;
const empty=(i,t,x,b='')=>`<div class="empty">${ico(i)}<b>${t}</b><div>${x}</div>${b?`<p>${b}</p>`:''}</div>`;
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('on'),2400)}
function modal(html){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="sheet" role="dialog" aria-modal="true">${html}</div>`;m.addEventListener('mousedown',e=>{if(e.target===m)m.remove()});document.body.append(m);const f=m.querySelector('input:not([disabled]),select,button');f&&f.focus();return m}
function confirmBox(msg,ok='Confirmar',danger=true){return new Promise(res=>{const m=modal(`<h3>Confirmação</h3><p>${msg}</p><div class="row"><button class="btn ghost" data-n>Cancelar</button><button class="btn ${danger?'danger':''}" data-y>${ok}</button></div>`);m.querySelector('[data-n]').onclick=()=>{m.remove();res(false)};m.querySelector('[data-y]').onclick=()=>{m.remove();res(true)}})}
function fld(f,v){const id='f_'+f.k,val=v??f.def??'';
 if(f.t==='check')return `<label class="chk"><input type="checkbox" name="${f.k}" ${val?'checked':''}> ${esc(f.l)}</label>`;
 let i;
 if(f.t==='select')i=`<select id="${id}" name="${f.k}">${f.o.map(([a,b])=>`<option value="${esc(a)}" ${String(a)===String(val)?'selected':''}>${esc(b)}</option>`).join('')}</select>`;
 else if(f.t==='area')i=`<textarea id="${id}" name="${f.k}" rows="3">${esc(val)}</textarea>`;
 else i=`<input id="${id}" name="${f.k}" type="${f.t==='num'?'text':f.t||'text'}" ${f.t==='num'?'inputmode="decimal"':''} ${f.t==='date'&&f.min?`min="${f.min}"`:''} ${f.t==='date'&&f.max?`max="${f.max}"`:''} value="${esc(val)}" ${f.dis?'disabled':''} autocomplete="${f.ac||'off'}">`;
 return `<div class="fld"><label for="${id}">${esc(f.l)}${f.r?' *':''}</label>${i}${f.h?`<small>${esc(f.h)}</small>`:''}</div>`}
function form(title,fields,vals,onSave,sub='Salvar'){
 const m=modal(`<h3>${esc(title)}</h3><form novalidate>${fields.map(f=>fld(f,vals[f.k])).join('')}<p class="err" role="alert"></p><div class="row"><button type="button" class="btn ghost" data-x>Cancelar</button><button class="btn" type="submit">${sub}</button></div></form>`);
 const fm=m.querySelector('form'),er=m.querySelector('.err');m.querySelector('[data-x]').onclick=()=>m.remove();
 fm.onsubmit=async e=>{e.preventDefault();const o={};const bad=t=>{er.textContent=t};
  for(const f of fields){if(f.dis){o[f.k]=vals[f.k];continue}const el=fm.elements[f.k];let v=f.t==='check'?el.checked:el.value.trim();
   if(f.t==='num'){if(v===''){if(f.r)return bad(`${f.l}: obrigatório`);v=null}else{v=num(v);if(v===null)return bad(`${f.l}: número inválido`);if((f.min!=null&&v<f.min)||(f.max!=null&&v>f.max))return bad(`${f.l}: use um valor entre ${f.min??'0'} e ${f.max??'∞'}`)}}
   else if(f.t==='date'){if(f.r&&!v)return bad(`${f.l}: obrigatório`);if(v&&!/^\d{4}-\d{2}-\d{2}$/.test(v))return bad(`${f.l}: data inválida`);if(v&&f.min&&v<f.min)return bad(`${f.l}: não pode ser antes de ${fmtD(f.min)}`);if(v&&f.max&&v>f.max)return bad(`${f.l}: não pode ser depois de ${fmtD(f.max)}`)}
   else if(f.r&&!v&&f.t!=='check')return bad(`${f.l}: obrigatório`);
   if(typeof v==='string'&&v.length>(f.t==='area'?1000:120))return bad(`${f.l}: texto longo demais`);
   o[f.k]=v}
  try{const r=await onSave(o);if(r)return bad(r)}catch(x){return bad('Erro ao salvar: '+x.message)}
  m.remove();await refresh();toast('Salvo ✓')}}
