const APP_VERSION='0.5.0';
const DEF={theme:'dark',waterGoal:2000,waterQuick:[200,300,500],stepGoal:8000,weighInterval:7,kcalAdjust:0,kcalOverride:null,protG:1.6,fatPct:25,runAuto:true,runAlert:true,runAlertEveryM:1000};
let S={},ui={tdate:ymd(),dwd:new Date().getDay(),range:30,fq:''};
async function load(){const o={};for(const t of db.tables)o[t.name]=await t.toArray();const kv=Object.fromEntries(o.kv.map(r=>[r.key,r]));
 S={...o,tpls:kv.mealTemplates?.items||[],profile:kv.profile||null,settings:{...DEF,...(kv.settings||{})},meta:kv.meta};S.weights.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0)}
const SEED_W=[
 [2,'Força A','15h–16h','25 min','Força A: agachamento 2x10; flexão apoiada 2x8; elevação de quadril 2x12; prancha 2x15s',[['Agachamento','2x10'],['Flexão apoiada','2x8'],['Elevação de quadril','2x12'],['Prancha','2x15s']]],
 [3,'Caminhada','15h–16h','20–25 min','Caminhada: 5 min confortável + 10–15 min ritmo moderado + 5 min confortável',[['Caminhada','5 min confortável + 10–15 min ritmo moderado + 5 min confortável']]],
 [4,'Recuperação e passeio com o cachorro','Livre','Livre','Recuperação e passeio habitual com o cachorro',[['Passeio habitual com o cachorro','']]],
 [5,'Força B','15h–16h','25 min','Força B: afundo com apoio 2x8 por perna; flexão na parede/apoiada 2x8; superman 2x10; panturrilha 2x15; prancha lateral 2x15s',[['Afundo com apoio','2x8 por perna'],['Flexão na parede/apoiada','2x8'],['Superman','2x10'],['Panturrilha','2x15'],['Prancha lateral','2x15s']]],
 [6,'Caminhada e corda opcional','15h–16h','20–30 min','Caminhada; corda opcional em intervalos curtos, somente se estiver confortável',[['Caminhada',''],['Corda (opcional)','intervalos curtos, somente se estiver confortável']]],
 [0,'Recuperação e passeio com o cachorro','Livre','Livre','Recuperação e passeio habitual com o cachorro',[['Passeio habitual com o cachorro','']]],
 [1,'Descanso e passeio com o cachorro','Livre','Livre','Descanso e passeio habitual com o cachorro',[['Passeio habitual com o cachorro','']]]];
const SEED_H=['Fiz refeições regulares e completas','Bebi água ao longo do dia','Respeitei meu descanso','Passeei com meu cachorro'];
async function seedUids(){for(const w of await db.workouts.toArray())if(!w.uid&&w.source==='planilha'){w.uid='seed-w-'+w.day;await db.workouts.put(w)}
 for(const h of await db.habits.toArray())if(!h.uid&&h.source==='planilha'){const i=SEED_H.indexOf(h.name);if(i>=0){h.uid='seed-h-'+i;await db.habits.put(h)}}}
async function seed(){if(S.meta)return;
 for(const [day,name,time,dur,orig,ex] of SEED_W)await db.workouts.add({uid:'seed-w-'+day,day,name,time,duration:dur,note:orig,source:'planilha',ex:ex.map(([n,p])=>({name:n,plan:p}))});
 for(const [i,name] of SEED_H.entries())await db.habits.add({uid:'seed-h-'+i,name,active:true,source:'planilha'});
 await db.kv.put({key:'meta',seeded:1,v:1,at:ymd()});await load()}
async function refresh(){await load();render();Sync.schedule()}
window.addEventListener('satori-synced',async()=>{await load();render()});window.addEventListener('online',()=>Sync.schedule());
const setKV=async(k,v)=>{await db.kv.put({...v,key:k})};
/* ===== Regras e cálculos ===== */
const lastW=()=>S.weights[S.weights.length-1];
const nextWeigh=()=>S.weights.length?addDays(lastW().date,S.settings.weighInterval):null;
const curKg=()=>lastW()?.kg??S.profile?.weight??null;
const ageFrom=b=>{const d=new Date(b+'T12:00'),n=new Date();let a=n.getFullYear()-d.getFullYear();if(n<new Date(n.getFullYear(),d.getMonth(),d.getDate()))a--;return a};
function calc(){return calcWith(S.profile||{},curKg(),S.settings)}
function calcWith(P,w,s){const miss=[],age=P.birth?ageFrom(P.birth):P.age;
 if(!age)miss.push('idade');if(!P.height)miss.push('altura');if(!w)miss.push('peso atual');if(!P.sex)miss.push('sexo biológico (a fórmula usa essa informação)');if(!P.activity)miss.push('nível de atividade');
 if(miss.length)return{miss};
 const bmr=10*w+6.25*P.height-5*age+(P.sex==='m'?5:-161),f=ACT[P.activity][1],tdee=bmr*f,auto=tdee+(+s.kcalAdjust||0),kcal=s.kcalOverride||auto;
 const p=s.protG*w,fat=kcal*s.fatPct/100/9,c=Math.max(0,(kcal-p*4-fat*9)/4);
 return{bmr,f,tdee,auto,kcal,p,fat,c,w,P,man:!!s.kcalOverride}}
const food=id=>S.foods.find(f=>f.id===id);
const nut=(f,q)=>{const k=q/(f.ref||100);return{kcal:f.kcal*k,p:f.p*k,c:f.c*k,f:f.f*k}};
const tot=a=>({kcal:sum(a,x=>x.kcal),p:sum(a,x=>x.p),c:sum(a,x=>x.c),f:sum(a,x=>x.f)});
const dayLog=d=>S.foodlog.filter(x=>x.date===d);
const dayTot=d=>tot(dayLog(d));
const planEntries=(wd,slot)=>S.plan.filter(x=>x.wd===wd&&(!slot||x.slot===slot)).map(x=>({...x,food:food(x.foodId)})).filter(x=>x.food).map(x=>({...x,...nut(x.food,x.qty)}));
const waterDay=d=>sum(S.water.filter(x=>x.date===d),x=>x.ml);
const stepsDay=d=>S.steps.find(x=>x.date===d)?.steps??null;
const hlog=(d,id)=>S.habitlog.find(x=>x.key===`${d}|${id}`);
const aHabits=()=>S.habits.filter(h=>h.active);
function consist(n=30,id=null){let done=0,reg=0;for(const d of days(n))for(const h of(id?S.habits.filter(x=>x.id===id):aHabits())){const l=hlog(d,h.id);if(l){reg++;if(l.done)done++}}return{done,reg,pct:reg?done/reg*100:null}}
function goalP(g){let st=g.start,cur=g.cur??g.start;
 if(g.kind==='peso'){st=g.start??S.weights[0]?.kg??null;cur=lastW()?.kg??null}
 if(g.kind==='consist'){st=0;cur=consist(30).pct}
 if(st==null||cur==null||g.target==null)return{pct:null,st,cur};
 const pct=g.target===st?(cur===g.target?100:0):(cur-st)/(g.target-st)*100;return{pct:clamp(pct),st,cur}}
const sessFor=(d,wid)=>S.sessions.find(x=>x.date===d&&x.wid===wid);
const wkFor=d=>S.workouts.filter(w=>w.day===D(d).getDay());
function sessProg(d){let done=0,total=0;for(const w of wkFor(d)){const s=sessFor(d,w.id);total+=w.ex.length;if(s)done+=s.items.filter(i=>i.done).length}return{done,total}}
/* ===== Gráficos SVG ===== */
function line(pts,{unit='',target=null}={}){if(!pts.length)return empty('chart','Sem registros no período','Registre dados para ver o gráfico.');
 const W=600,H=190,L=38,R=12,T=14,B=26,xs=pts.map(p=>D(p.x).getTime()),x0=Math.min(...xs),x1=Math.max(...xs),ys=pts.map(p=>p.y).concat(target!=null?[target]:[]);
 let lo=Math.min(...ys),hi=Math.max(...ys);if(lo===hi){lo-=1;hi+=1}const pd=(hi-lo)*.15;lo-=pd;hi+=pd;
 const X=t=>x1===x0?(L+W-R)/2:L+(t-x0)/(x1-x0)*(W-L-R),Y=v=>T+(1-(v-lo)/(hi-lo))*(H-T-B);
 const path=pts.map((p,i)=>`${i?'L':'M'}${X(xs[i]).toFixed(1)} ${Y(p.y).toFixed(1)}`).join(' ');
 return `<svg class="ch" viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de linha, ${pts.length} registros">${[0,.5,1].map(f=>{const v=lo+(hi-lo)*f;return `<line class="gl" x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}"/><text x="2" y="${Y(v)+4}">${r1(v)}</text>`}).join('')}
 ${target!=null?`<line x1="${L}" x2="${W-R}" y1="${Y(target)}" y2="${Y(target)}" stroke="var(--kc)" stroke-dasharray="5 4"/><text x="${W-R-60}" y="${Y(target)-4}" style="fill:var(--kc)">meta ${target}${unit}</text>`:''}
 <path d="${path}" fill="none" stroke="var(--ac)" stroke-width="2.5" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${X(xs[i])}" cy="${Y(p.y)}" r="4" fill="var(--ac)"><title>${fmtD(p.x)}: ${p.y}${unit}</title></circle>`).join('')}
 <text x="${L}" y="${H-6}">${fmtD(pts[0].x)}</text><text x="${W-R}" y="${H-6}" text-anchor="end">${fmtD(pts[pts.length-1].x)}</text></svg>`}
function bars(items,{goal=null,color='var(--ac)',unit=''}={}){const W=600,H=170,L=38,B=22,T=10,mx=Math.max(1,goal||0,...items.map(i=>i.v)),bw=(W-L-8)/items.length,Y=v=>T+(1-v/mx)*(H-T-B);
 if(!items.some(i=>i.v>0))return empty('chart','Sem registros no período','Os dados aparecem aqui conforme você registra.');
 return `<svg class="ch" viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de barras, ${items.length} dias"><line class="gl" x1="${L}" x2="${W-8}" y1="${Y(0)}" y2="${Y(0)}"/><text x="2" y="${Y(mx)+8}">${r0(mx)}</text>
 ${items.map((i,k)=>i.v>0?`<rect x="${L+k*bw+bw*.15}" y="${Y(i.v)}" width="${bw*.7}" height="${Y(0)-Y(i.v)}" rx="3" fill="${color}"><title>${fmtD(i.d)}: ${r1(i.v)}${unit}</title></rect>`:'').join('')}
 ${goal?`<line x1="${L}" x2="${W-8}" y1="${Y(goal)}" y2="${Y(goal)}" stroke="var(--kc)" stroke-dasharray="5 4"/>`:''}
 <text x="${L}" y="${H-5}">${fmtD(items[0].d)}</text><text x="${W-8}" y="${H-5}" text-anchor="end">${fmtD(items[items.length-1].d)}</text></svg>`}
const ring=(p,c,t)=>{const R=40,C=2*Math.PI*R;return `<div class="ring"><svg width="96" height="96" viewBox="0 0 96 96"><circle cx="48" cy="48" r="${R}" fill="none" stroke="var(--s2)" stroke-width="10"/><circle cx="48" cy="48" r="${R}" fill="none" stroke="${c}" stroke-width="10" stroke-linecap="round" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-clamp(p)/100)}" style="transition:stroke-dashoffset .6s"/></svg><div>${t}</div></div>`};
const macroRow=(l,v,g,c)=>`<div style="margin:8px 0"><div class="row sp sm"><span>${l}</span><span>${r0(v)}${g?` / ${r0(g)}`:''} g</span></div>${bar(g?v/g*100:0,c)}</div>`;
